<<<WHOLE
fn srgb_to_linear(c: f32) -> f32 {
  if c <= 0.04045 {
    c / 12.92;
  } else {
    pow((c + 0.055) / 1.055, 2.4);
  }
}

fn linear_to_srgb(c: f32) -> f32 {
  if c <= 0.0031308 {
    c * 12.92;
  } else {
    1.055 * pow(c, 1.0 / 2.4) - 0.055;
  }
}

fn srgb_color_to_linear(srgb: color) -> vec3 {
  vec3(
    srgb_to_linear(srgb.x),
    srgb_to_linear(srgb.y),
    srgb_to_linear(srgb.z)
  );
}

material Sweep {
  surface: fragment() {
    let input: SurfaceInput;
    let x = input.position.x;
    let t = frame.time;

    let w = 0.5 + 0.5 * sin(0.8 * x + t);

    let a_srgb = color(0.1, 0.137, 0.494, 1.0);
    let b_srgb = color(1.0, 0.702, 0.0, 1.0);

    let a_linear = srgb_color_to_linear(a_srgb);
    let b_linear = srgb_color_to_linear(b_srgb);

    let blended_linear = (1.0 - w) * a_linear + w * b_linear;

    vec4(blended_linear.x, blended_linear.y, blended_linear.z, 1.0);
  };

  lighting: Unlit;
}
>>>END
>>>

